function PublicHeader() { return <header className="flex items-center justify-between border-b border-[#d7dddc] bg-[#f6f4ef] px-4 py-4 sm:px-8"><Link href="/" className="rn-focus rounded-lg"><BrandLockup /></Link><nav className="hidden items-center gap-6 md:flex"><a href="#how-it-works" className="text-xs font-extrabold uppercase tracking-[0.1em] text-[#52626c] hover:text-[#0e4e78]">How it works</a><a href="#safety" className="text-xs font-extrabold uppercase tracking-[0.1em] text-[#52626c] hover:text-[#0e4e78]">Safety</a><Link href="/login" className="rn-focus text-xs font-extrabold uppercase tracking-[0.1em] text-[#0e4e78]">Sign in</Link><Link href="/roles" className="rn-focus rounded-lg bg-[#0e4e78] px-4 py-3 text-xs font-extrabold uppercase tracking-[0.1em] text-white">Choose a role</Link></nav><Link href="/login" className="rn-focus rounded-lg border border-[#cbd5d6] px-3 py-2 text-xs font-extrabold text-[#0e4e78] md:hidden">Sign in</Link></header>; }

export function LandingPage() { return <div className="min-h-screen bg-[#f6f4ef]"><PublicHeader /><main><section className="relative overflow-hidden border-b border-[#d7dddc]"><div className="mx-auto grid max-w-[1440px] gap-0 lg:grid-cols-[0.86fr_1.14fr]"><div className="relative z-10 px-6 py-14 sm:px-10 sm:py-20 lg:px-14 lg:py-28"><div className="rn-eyebrow"><Activity className="h-3.5 w-3.5 text-[#d83232]" />Community emergency response</div><h1 className="mt-5 max-w-xl text-5xl font-extrabold leading-[0.96] tracking-[-0.065em] text-[#17212b] sm:text-6xl lg:text-7xl">Help should not wait for distance.</h1><p className="mt-6 max-w-lg text-base font-medium leading-7 text-[#52626c]">RANEEV connects people in distress with verified nearby responders—so help can begin while professional services are on the way.</p><div className="mt-9 flex flex-col gap-3 sm:flex-row"><Link href="/roles" className="rn-focus flex min-h-14 items-center justify-center gap-3 rounded-xl bg-[#d83232] px-6 text-sm font-extrabold text-white shadow-[var(--rn-shadow-md)] hover:bg-[#b82727]">Request nearby help <ArrowRight className="h-4 w-4" /></Link><Link href="/volunteer" className="rn-focus flex min-h-14 items-center justify-center gap-3 rounded-xl border border-[#b9c8cf] bg-white px-6 text-sm font-extrabold text-[#0e4e78] hover:bg-[#e2eff6]">I am a responder <UserRoundCheck className="h-4 w-4" /></Link></div><p className="mt-5 flex items-center gap-2 text-xs font-bold text-[#60707c]"><ShieldCheck className="h-4 w-4 text-[#247352]" />RANEEV complements professional emergency services. Call them whenever possible.</p></div><div className="relative min-h-[28rem] border-t border-[#d7dddc] lg:border-l lg:border-t-0"><img src={assets.mapHero} alt="RANEEV emergency coordination map" className="absolute inset-0 h-full w-full object-cover" /><div className="absolute inset-x-5 bottom-5 max-w-sm rounded-xl border border-white/80 bg-white p-5 shadow-[var(--rn-shadow-lg)] sm:left-8"><div className="flex items-center justify-between"><StatusBadge tone="critical" label="ERN active" /><span className="rn-mono text-[0.65rem] font-semibold text-[#60707c]">ERN-2408-184</span></div><h2 className="mt-4 text-xl font-extrabold tracking-[-0.04em] text-[#17212b]">Responder search in progress</h2><p className="mt-2 text-sm font-medium leading-6 text-[#52626c]">Verified responders are ranked by distance, availability, and relevant skills.</p><div className="mt-4 flex items-center gap-2 border-t border-[#edf0ee] pt-4 text-xs font-extrabold text-[#0e4e78]"><Navigation className="h-4 w-4" />2.4 km to nearest available responder</div></div></div></div></section>
  <section id="how-it-works" className="mx-auto max-w-[1440px] px-6 py-16 sm:px-10 lg:px-14"><div className="grid gap-10 lg:grid-cols-[0.64fr_1.36fr]"><div><div className="rn-eyebrow">Three reliable steps</div><h2 className="mt-3 text-3xl font-extrabold tracking-[-0.05em] text-[#17212b]">A clear path under pressure.</h2></div><div className="grid gap-4 md:grid-cols-3">{[["01", "Confirm", "Choose an emergency category and check your location."], ["02", "Connect", "RANEEV identifies nearby verified responders."], ["03", "Coordinate", "Track status and communicate until help arrives."]].map(([num, title, text]) => <div key={num} className="border-t-4 border-[#0e4e78] bg-white p-5 shadow-[var(--rn-shadow-sm)]"><span className="rn-mono text-xs font-bold text-[#0e4e78]">{num}</span><h3 className="mt-5 text-lg font-extrabold text-[#17212b]">{title}</h3><p className="mt-2 text-sm font-medium leading-6 text-[#60707c]">{text}</p></div>)}</div></div></section>
  <section id="safety" className="border-y border-[#d7dddc] bg-[#e2eff6]"><div className="mx-auto grid max-w-[1440px] gap-10 px-6 py-14 sm:px-10 lg:grid-cols-2 lg:px-14"><div><div className="rn-eyebrow text-[#0e4e78]"><ShieldCheck className="h-3.5 w-3.5" />Safety by design</div><h2 className="mt-3 text-3xl font-extrabold tracking-[-0.05em] text-[#17212b]">People see only what they need to respond.</h2><div className="rn-context-band"><span className="rn-mono text-[#0e4e78]">ACCESS/SCOPED</span><span className="rn-route-line w-7" /><span>least information necessary</span></div></div><div className="grid gap-4 sm:grid-cols-2"><div className="border-l-4 border-[#0e4e78] bg-white p-5"><MapPin className="h-5 w-5 text-[#0e4e78]" /><h3 className="mt-4 font-extrabold">Location is scoped</h3><p className="mt-2 text-sm font-medium leading-6 text-[#52626c]">Exact location is limited to verified, authorized participants during an active incident.</p></div><div className="border-l-4 border-[#247352] bg-white p-5"><UserRoundCheck className="h-5 w-5 text-[#0e4e78]" /><h3 className="mt-4 font-extrabold">Responders are reviewed</h3><p className="mt-2 text-sm font-medium leading-6 text-[#52626c]">Volunteer availability and skills are designed to be verified before dispatch.</p></div></div></div></section></main><footer className="flex flex-col gap-3 border-t border-[#d7dddc] px-6 py-7 text-xs font-semibold text-[#60707c] sm:flex-row sm:items-center sm:justify-between sm:px-10 lg:px-14"><BrandLockup compact /><span>RANEEV complements professional emergency services.</span></footer></div>; }

const roleDashboardPath = (role: "citizen" | "volunteer" | "coordinator" | "admin") => role === "citizen" ? "/citizen" : `/${role}`;

export function AuthPage({ kind }: { kind: "login" | "register" }) { const isLogin = kind === "login"; const [, setLocation] = useLocation(); const utils = trpc.useUtils(); const [name, setName] = useState(""); const [email, setEmail] = useState(""); const [password, setPassword] = useState(""); const login = trpc.auth.login.useMutation({ onSuccess: user => { utils.auth.me.setData(undefined, user); setLocation(roleDashboardPath(user.role)); } }); const register = trpc.auth.register.useMutation({ onSuccess: user => { utils.auth.me.setData(undefined, user); setLocation(roleDashboardPath(user.role)); } }); const pending = login.isPending || register.isPending; const submit = async (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); try { if (isLogin) await login.mutateAsync({ email, password }); else await register.mutateAsync({ name, email, password, role: "citizen" }); } catch (error) { toast(error instanceof Error ? error.message : "Secure access could not be completed."); } }; return <div className="min-h-screen bg-[#f6f4ef]"><PublicHeader /><main className="mx-auto grid min-h-[calc(100vh-5rem)] max-w-[1440px] lg:grid-cols-[0.8fr_1.2fr]"><div className="order-2 px-6 py-10 sm:px-10 lg:order-1 lg:px-14 lg:py-16"><BackLink href="/" label="Back to RANEEV" /><div className="max-w-md"><div className="rn-eyebrow"><ShieldCheck className="h-3.5 w-3.5" />Secure access</div><h1 className="mt-3 text-4xl font-extrabold tracking-[-0.06em] text-[#17212b]">{isLogin ? "Continue to your workspace." : "Create your RANEEV profile."}</h1><p className="mt-3 text-sm font-medium leading-6 text-[#60707c]">{isLogin ? "Use your verified account to view protected emergency information." : "Role and identity verification are completed before responder access is granted."}</p><form className="mt-8 space-y-4" onSubmit={submit}>{!isLogin && <label className="block"><span className="text-xs font-extrabold text-[#43535e]">Full name</span><input value={name} onChange={event => setName(event.target.value)} className="rn-focus mt-2 min-h-12 w-full rounded-lg border border-[#cbd5d6] bg-white px-3 text-sm font-semibold" placeholder="Your full name" /></label>}<label className="block"><span className="text-xs font-extrabold text-[#43535e]">Email or phone</span><input type="email" value={email} onChange={event => setEmail(event.target.value)} className="rn-focus mt-2 min-h-12 w-full rounded-lg border border-[#cbd5d6] bg-white px-3 text-sm font-semibold" placeholder="name@example.com" /></label><label className="block"><span className="text-xs font-extrabold text-[#43535e]">Password</span><input type="password" value={password} onChange={event => setPassword(event.target.value)} className="rn-focus mt-2 min-h-12 w-full rounded-lg border border-[#cbd5d6] bg-white px-3 text-sm font-semibold" placeholder="••••••••" /></label><Button disabled={pending} className="rn-touch mt-2 w-full bg-[#0e4e78] font-extrabold hover:bg-[#0b3e61]">{isLogin ? "Sign in securely" : "Continue to role selection"}</Button></form><p className="mt-5 text-center text-xs font-semibold text-[#60707c]">{isLogin ? "New to RANEEV?" : "Already have an account?"} <Link href={isLogin ? "/register" : "/login"} className="font-extrabold text-[#0e4e78]">{isLogin ? "Register" : "Sign in"}</Link></p><div className="mt-8"><StatePreview compact /></div></div></div><div className="order-1 relative min-h-[22rem] border-b border-[#d7dddc] lg:order-2 lg:border-b-0 lg:border-l"><img src={assets.responder} alt="Verified community responder" className="absolute inset-0 h-full w-full object-cover" /><div className="absolute inset-x-5 bottom-5 rounded-xl bg-[#17212b] p-5 text-white sm:inset-x-8 sm:bottom-8"><p className="rn-eyebrow text-white/55">RANEEV access principle</p><p className="mt-2 text-xl font-extrabold tracking-[-0.04em]">Protect the people, protect the response.</p><p className="mt-2 text-sm font-medium leading-6 text-white/70">Authentication, role access, and exact location sharing will be enforced by the backend implementation.</p></div></div></main></div>; }

export function AccessDenied() { return <div className="min-h-screen bg-[#f6f4ef]"><PublicHeader /><main className="mx-auto flex min-h-[calc(100vh-5rem)] max-w-[1440px] items-center px-6 py-12 sm:px-10 lg:px-14"><SurfaceCard tone="critical" className="max-w-xl p-8"><div className="rn-eyebrow"><ShieldCheck className="h-3.5 w-3.5" />Access denied</div><h1 className="mt-3 text-4xl font-extrabold tracking-[-0.06em] text-[#17212b]">This workspace is not available to your account.</h1><p className="mt-3 text-sm font-medium leading-6 text-[#60707c]">RANEEV verifies both session identity and role permission before opening protected response information.</p><Link href="/login" className="rn-focus mt-7 inline-flex min-h-12 items-center rounded-lg bg-[#0e4e78] px-5 text-sm font-extrabold text-white hover:bg-[#0b3e61]">Return to secure sign in</Link></SurfaceCard></main></div>; }

export function RoleSelection() { const cards = [["Citizen", "Request verified nearby help and follow the incident response.", "/citizen", HeartPulse, "Use when you need help or are reporting for someone nearby."], ["Volunteer", "Maintain availability, review emergency requests, and coordinate a response.", "/volunteer", UserRoundCheck, "Verification is required before receiving incidents."], ["Coordinator", "Monitor active incidents, responders, and escalation signals.", "/coordinator", Activity, "Operational workspace for designated coordinators."], ["Administrator", "Review users, verification, incidents, and security audit activity.", "/admin", ShieldCheck, "Restricted platform administration workspace."]] as const; return <div className="min-h-screen bg-[#f6f4ef]"><PublicHeader /><main className="mx-auto max-w-[1200px] px-6 py-12 sm:px-10 lg:py-16"><BackLink href="/" label="Back to RANEEV" /><div className="max-w-2xl"><div className="rn-eyebrow">Role routing</div><h1 className="mt-3 text-4xl font-extrabold tracking-[-0.06em] text-[#17212b]">Choose the workspace you need.</h1><p className="mt-3 text-sm font-medium leading-6 text-[#60707c]">These screens are interactive interface previews. Backend identity and access control will determine which workspace is available to each person.</p></div><div className="mt-10 grid gap-4 md:grid-cols-2">{cards.map(([title, description, href, Icon, note]) => <Link key={title} href={href} className="rn-focus group relative overflow-hidden rounded-xl border border-[#cbd5d6] bg-white p-6 shadow-[var(--rn-shadow-sm)] transition-transform hover:-translate-y-0.5 hover:shadow-[var(--rn-shadow-md)]"><div className="flex items-start justify-between"><span className="flex h-12 w-12 items-center justify-center rounded-xl bg-[#e2eff6] text-[#0e4e78]"><Icon className="h-6 w-6" /></span><ChevronRight className="h-5 w-5 text-[#60707c] transition-transform group-hover:translate-x-1" /></div><h2 className="mt-7 text-xl font-extrabold tracking-[-0.04em] text-[#17212b]">{title}</h2><p className="mt-2 text-sm font-medium leading-6 text-[#52626c]">{description}</p><p className="mt-6 border-t border-[#edf0ee] pt-4 text-xs font-bold text-[#60707c]">{note}</p></Link>)}</div><div className="mt-8"><StatePreview compact /></div></main></div>; }

function IncidentRow({ incident, detailed = false }: { incident: typeof incidents[number]; detailed?: boolean }) { return <div className="flex flex-col gap-3 border-b border-[#edf0ee] py-4 last:border-b-0 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-start gap-3"><span className={`mt-1 h-2.5 w-2.5 shrink-0 rounded-full ${incident.tone === "critical" ? "bg-[#d83232]" : incident.tone === "warning" ? "bg-[#b86d0a]" : "bg-[#247352]"}`} /><div><p className="text-sm font-extrabold text-[#17212b]">{incident.title}</p><p className="mt-1 text-xs font-semibold text-[#60707c]">{incident.id} · {incident.location} · {incident.time}</p>{detailed && <p className="mt-2 text-xs font-medium text-[#52626c]">Primary responder: {incident.responder}</p>}</div></div><div className="flex items-center gap-3"><StatusBadge tone={incident.tone} label={incident.status} /><ChevronRight className="h-4 w-4 text-[#60707c]" /></div></div>; }

export function CitizenPortal({ page, publicId }: { page?: string; publicId?: string }) { const view = page ?? "home"; const content = view === "report" ? <CitizenRequestReport /> : view === "confirm" ? <CitizenRequestConfirm /> : view === "live" ? <><CitizenRequestLive publicId={publicId} /><CitizenSafeAiStatus publicId={publicId} /></> : view === "history" ? <CitizenRequestHistory /> : view === "profile" ? <CitizenProfile /> : <CitizenRequestHome />; return <ConsoleShell role="citizen">{content}</ConsoleShell>; }

function CitizenSafeAiStatus({ publicId }: { publicId?: string }) {
  const active = trpc.incidents.active.useQuery(undefined, { enabled: !publicId, refetchInterval: 8_000 });
  const incidentId = publicId ?? active.data?.publicId;
  const input = useMemo(() => ({ publicId: incidentId ?? "pending" }), [incidentId]);
  const status = trpc.ai.citizenStatus.useQuery(input, { enabled: Boolean(incidentId), refetchInterval: 12_000 });
  if (!incidentId || status.isLoading) return null;
  return <div className="mt-4"><OperationalAlert tone="info" title="Coordination update">{status.data?.message ?? "Your request remains under active coordination. Responder matching continues normally."}</OperationalAlert></div>;
}

const emergencyOptions: Array<{ key: CitizenEmergencyType; title: string; detail: string }> = [
  { key: "medical", title: "Medical emergency", detail: "Collapse, breathing concern, severe pain" },
  { key: "road_accident", title: "Road accident", detail: "Vehicle incident or roadside injury" },
  { key: "injury", title: "Injury", detail: "Fall, wound, or assistance needed" },
  { key: "fire", title: "Fire concern", detail: "Small fire or immediate safety support" },
  { key: "unconscious", title: "Unconscious person", detail: "Person not responding" },
  { key: "other", title: "Other", detail: "Describe the immediate situation" },
];

const emergencyLabel: Record<CitizenEmergencyType, string> = { medical: "Medical emergency", road_accident: "Road accident", injury: "Injury", fire: "Fire concern", unconscious: "Unconscious person", other: "Other" };

function incidentTone(status: string) { return status === "resolved" ? "safe" as const : status === "arrived" ? "safe" as const : status === "searching" ? "warning" as const : "critical" as const; }
function incidentStatusLabel(status: string) { return status === "searching" ? "Searching responders" : status === "accepted" ? "Responder accepted" : status === "en_route" ? "Responder en route" : status === "arrived" ? "Help arrived" : status === "resolved" ? "Incident resolved" : "Emergency request"; }

function CitizenRequestHome() {
  const [, setLocation] = useLocation();
  const active = trpc.incidents.active.useQuery(undefined, { refetchInterval: 8_000 });
  useEffect(() => { if (active.data?.publicId) setLocation(`/citizen/live/${active.data.publicId}`); }, [active.data?.publicId, setLocation]);
  if (active.isLoading) return <><PageHeading eyebrow="Citizen home" title="Checking active emergency status." description="RANEEV is confirming whether an emergency request is already active for this account." /><SurfaceCard tone="info" className="p-6"><p className="text-sm font-extrabold">Loading protected incident status…</p></SurfaceCard></>;
  return <><PageHeading eyebrow="Citizen home" title="Emergency status: no active request." description="If someone needs immediate help, begin with a clear category and confirmed location. RANEEV will show the verified next action at each step." action={<Link href="/citizen/report" className="rn-focus flex min-h-12 items-center justify-center gap-2 rounded-md bg-[#d83232] px-5 text-sm font-extrabold text-white hover:bg-[#b82727]"><AlertTriangle className="h-4 w-4" />Request emergency help</Link>} /><div className="grid gap-5 xl:grid-cols-[1.15fr_0.85fr]"><SurfaceCard tone="info" className="p-6"><div className="flex items-start justify-between gap-4"><div><StatusBadge tone="safe" label="No active incident" /><h2 className="mt-5 text-2xl font-extrabold tracking-[-0.05em]">Start with the facts you know.</h2><p className="mt-2 max-w-lg text-sm font-medium leading-6 text-[#52626c]">Choose an emergency category, confirm the location, add an optional note, and review the request before RANEEV begins a responder search.</p></div><HeartPulse className="h-10 w-10 shrink-0 text-[#0e4e78]" /></div><div className="mt-7 grid gap-0 border-y border-[#d7dddc] sm:grid-cols-3">{[["01", "Choose", "Emergency type"], ["02", "Confirm", "Location + note"], ["03", "Request", "Verified help"]].map(([n, a, b], index) => <div key={n} className={`bg-[#f4f7f7] p-3 ${index > 0 ? "border-t border-[#d7dddc] sm:border-l sm:border-t-0" : ""}`}><span className="rn-mono text-xs font-bold text-[#0e4e78]">{n}</span><p className="mt-2 text-sm font-extrabold">{a}</p><p className="text-xs font-semibold text-[#60707c]">{b}</p></div>)}</div></SurfaceCard><div className="space-y-4"><OperationalAlert tone="warning" title="Location accuracy matters">Move to an open area or adjust the location details if they appear inaccurate.</OperationalAlert><SurfaceCard tone="neutral" className="p-5"><div className="flex items-center justify-between"><div><p className="rn-eyebrow">Emergency history</p><p className="mt-2 text-sm font-extrabold">View your verified response records</p></div><Link href="/citizen/history" className="rn-focus text-xs font-extrabold text-[#0e4e78]">View history</Link></div></SurfaceCard></div></div><div className="mt-6"><StatePreview /></div></>;
}

function CitizenRequestReport() {
  const [, setLocation] = useLocation();
  const { draft, updateDraft } = useEmergencyDraft();
  return <><BackLink href="/citizen" label="Citizen home" /><PageHeading eyebrow="Emergency reporting · step 1 of 3" title="What kind of help is needed?" description="Choose the closest operational category. This is not a medical diagnosis. You can add a short note before confirming the request." /><div className="grid gap-6 xl:grid-cols-[1fr_0.62fr]"><SurfaceCard tone="critical" className="p-6"><div className="grid gap-3 sm:grid-cols-2">{emergencyOptions.map(option => <button key={option.key} onClick={() => updateDraft({ emergencyType: option.key })} className={`rn-focus min-h-28 rounded-xl border p-4 text-left ${draft.emergencyType === option.key ? "border-[#0e4e78] bg-[#e2eff6]" : "border-[#d7dddc] bg-white hover:border-[#0e4e78]"}`}><p className="text-sm font-extrabold text-[#17212b]">{option.title}</p><p className="mt-2 text-xs font-medium leading-5 text-[#60707c]">{option.detail}</p></button>)}</div><div className="mt-6 flex justify-end"><Button onClick={() => setLocation("/citizen/confirm")} className="rn-focus min-h-12 gap-2 rounded-xl bg-[#0e4e78] px-5 text-sm font-extrabold text-white hover:bg-[#0b3e61]">Continue to location <ArrowRight className="h-4 w-4" /></Button></div></SurfaceCard><div className="space-y-4"><OperationalAlert tone="critical" title="If there is immediate danger">Contact local professional emergency services first whenever available. RANEEV coordinates nearby community help.</OperationalAlert><SurfaceCard tone="info" className="p-5"><p className="rn-eyebrow">Selected emergency type</p><p className="mt-3 text-sm font-extrabold">{emergencyLabel[draft.emergencyType]}</p><p className="mt-2 text-xs font-medium leading-5 text-[#60707c]">Location detection and an optional description are captured before the protected request is sent.</p></SurfaceCard><StatePreview compact /></div></div></>;
}

function CitizenRequestConfirm() {
  const [, setLocation] = useLocation();
  const { draft, updateDraft } = useEmergencyDraft();
  const utils = trpc.useUtils();
  const [locationState, setLocationState] = useState<"ready" | "locating" | "updated" | "unavailable">("ready");
  const create = trpc.incidents.create.useMutation({ onSuccess: incident => { utils.incidents.active.invalidate(); utils.incidents.mine.invalidate(); setLocation(`/citizen/live/${incident.publicId}`); } });
  const useDetectedLocation = () => {
    if (!navigator.geolocation) { setLocationState("unavailable"); toast("Current location is unavailable on this device. You can continue with the confirmed location."); return; }
    setLocationState("locating");
    navigator.geolocation.getCurrentPosition(position => {
      updateDraft({ latitude: position.coords.latitude, longitude: position.coords.longitude, accuracyMeters: Math.round(position.coords.accuracy), locationLabel: `Current location · ${position.coords.latitude.toFixed(5)}, ${position.coords.longitude.toFixed(5)}` });
      setLocationState("updated");
    }, () => { setLocationState("unavailable"); toast("RANEEV could not refresh current location. The confirmed location remains available."); }, { enableHighAccuracy: true, timeout: 10_000, maximumAge: 15_000 });
  };
  const submit = async () => { try { await create.mutateAsync({ emergencyType: draft.emergencyType, locationLabel: draft.locationLabel, latitude: draft.latitude, longitude: draft.longitude, accuracyMeters: draft.accuracyMeters, description: draft.description || undefined }); } catch (error) { toast(error instanceof Error ? error.message : "Emergency request could not be created."); } };
  const previewMap = useMemo(() => ({ incident: { id: "incident-preview", kind: "incident" as const, title: "Confirmed incident location", position: { lat: draft.latitude, lng: draft.longitude } }, currentLocation: locationState === "updated" ? { id: "current-location", kind: "current" as const, title: "Your current location", position: { lat: draft.latitude, lng: draft.longitude } } : undefined }), [draft.latitude, draft.longitude, locationState]);
  return <><BackLink href="/citizen/report" label="Edit emergency type" /><PageHeading eyebrow="Emergency reporting · step 2 of 3" title="Confirm location and details." description="Review the category, detected location, and optional short description before the responder search begins." /><div className="grid gap-6 xl:grid-cols-[1fr_0.65fr]"><EmergencyMap data={previewMap} label="Incident location preview" /><div className="space-y-4"><SurfaceCard tone="critical" className="p-6"><StatusBadge tone="critical" label={emergencyLabel[draft.emergencyType]} /><label className="mt-5 block"><span className="rn-eyebrow">Detected location</span><input value={draft.locationLabel} onChange={event => updateDraft({ locationLabel: event.target.value })} className="rn-focus mt-2 min-h-12 w-full rounded-lg border border-[#cbd5d6] bg-white px-3 text-sm font-extrabold text-[#17212b]" /></label><div className="mt-3 flex items-center justify-between gap-3"><p className="text-xs font-semibold text-[#60707c]">Location precision: {draft.accuracyMeters} m · {locationState === "updated" ? "current location updated" : "coordinates confirmed"}</p><button onClick={useDetectedLocation} disabled={locationState === "locating"} className="rn-focus text-xs font-extrabold text-[#0e4e78] disabled:opacity-60">{locationState === "locating" ? "Locating…" : "Use current location"}</button></div><label className="mt-5 block border-y border-[#edf0ee] py-4"><span className="rn-eyebrow">Optional description</span><textarea value={draft.description} onChange={event => updateDraft({ description: event.target.value })} maxLength={500} placeholder="Describe the immediate situation in a few words." className="rn-focus mt-2 min-h-24 w-full resize-y rounded-lg border border-[#cbd5d6] bg-white p-3 text-sm font-semibold text-[#43535e]" /></label><Button disabled={create.isPending} onClick={submit} className="rn-touch mt-5 w-full bg-[#d83232] text-sm font-extrabold text-white hover:bg-[#b82727]">{create.isPending ? "Creating emergency request…" : "Confirm emergency request"}</Button><p className="mt-3 text-center text-xs font-semibold text-[#60707c]">RANEEV will begin a responder search only after the server confirms this request.</p></SurfaceCard><DetailDialog /><StatePreview compact /></div></div></>;
}

function CitizenRequestLive({ publicId }: { publicId?: string }) {
  const [, setLocation] = useLocation();
  const active = trpc.incidents.active.useQuery(undefined, { refetchInterval: 8_000 });
  const incidentId = publicId ?? active.data?.publicId;
  const incidentQueryInput = useMemo(() => ({ publicId: incidentId ?? "pending" }), [incidentId]);
  const detail = trpc.incidents.byPublicId.useQuery(incidentQueryInput, { enabled: Boolean(incidentId), refetchInterval: 8_000 });
  const timeline = trpc.incidents.timeline.useQuery(incidentQueryInput, { enabled: Boolean(incidentId), refetchInterval: 8_000 });
  const mapSnapshot = trpc.incidents.mapSnapshot.useQuery(incidentQueryInput, { enabled: Boolean(incidentId), refetchInterval: 3_000 });
  const utils = trpc.useUtils();
  const refreshIncident = () => { utils.incidents.active.invalidate(); if (incidentId) { utils.incidents.byPublicId.invalidate({ publicId: incidentId }); utils.incidents.timeline.invalidate({ publicId: incidentId }); utils.incidents.mapSnapshot.invalidate({ publicId: incidentId }); } };
  const simulate = trpc.incidents.simulateProgress.useMutation({ onSuccess: refreshIncident });
  const resolve = trpc.incidents.resolve.useMutation({ onSuccess: refreshIncident });
  const simulateMovement = trpc.incidents.simulateResponderMovement.useMutation({ onSuccess: refreshIncident });
  const [currentLocation, setCurrentLocation] = useState<{ lat: number; lng: number } | null>(null);
  const [routeMetrics, setRouteMetrics] = useState<RouteMetrics | null>(null);
  const onRouteMetrics = useCallback((metrics: RouteMetrics | null) => setRouteMetrics(current => current?.distanceMeters === metrics?.distanceMeters && current?.durationSeconds === metrics?.durationSeconds ? current : metrics), []);
  useEffect(() => { if (!navigator.geolocation) return; navigator.geolocation.getCurrentPosition(position => setCurrentLocation({ lat: position.coords.latitude, lng: position.coords.longitude }), () => undefined, { enableHighAccuracy: true, timeout: 8_000, maximumAge: 30_000 }); }, []);
  useEffect(() => { if (!publicId && active.data?.publicId) setLocation(`/citizen/live/${active.data.publicId}`); }, [active.data?.publicId, publicId, setLocation]);
  const incident = detail.data;
  if (detail.isLoading || active.isLoading) return <><PageHeading eyebrow="Active emergency" title="Loading verified incident status." description="RANEEV is retrieving the latest protected response information." /><SurfaceCard tone="info" className="p-6"><p className="text-sm font-extrabold">Loading incident and responder status…</p></SurfaceCard></>;
  if (!incident) return <><PageHeading eyebrow="Active emergency" title="No active emergency request." description="There is no active citizen incident to track from this workspace." action={<Link href="/citizen/report" className="rn-focus rounded-md bg-[#d83232] px-5 py-3 text-sm font-extrabold text-white">Request help</Link>} /><StatePreview /></>;
  const status = incident.status;
  const arrived = status === "arrived";
  const resolved = status === "resolved";
  const advance = async () => { try { if (arrived) await resolve.mutateAsync({ publicId: incident.publicId }); else await simulate.mutateAsync({ publicId: incident.publicId }); } catch (error) { toast(error instanceof Error ? error.message : "Response status could not be updated."); } };
  const moveResponder = async () => { try { await simulateMovement.mutateAsync({ publicId: incident.publicId }); } catch (error) { toast(error instanceof Error ? error.message : "Responder position could not be updated."); } };
  if (resolved) return <CitizenRequestResolved incident={incident} />;
  const actionLabel = status === "searching" ? "Simulate responder acceptance" : status === "accepted" ? "Simulate responder departure" : status === "en_route" ? "Simulate help arrival" : "Confirm incident resolved";
  const mapData = { incident: { id: incident.publicId, kind: "incident" as const, title: "Emergency incident", position: { lat: incident.latitudeE6 / 1_000_000, lng: incident.longitudeE6 / 1_000_000 } }, responder: mapSnapshot.data?.responder ? { id: `responder-${mapSnapshot.data.responder.userId}`, kind: "responder" as const, title: mapSnapshot.data.responder.name, position: { lat: mapSnapshot.data.responder.latitude, lng: mapSnapshot.data.responder.longitude } } : undefined, currentLocation: currentLocation ? { id: "citizen-current", kind: "current" as const, title: "Your current location", position: currentLocation } : undefined };
  const routeDistance = routeMetrics ? `${(routeMetrics.distanceMeters / 1000).toFixed(1)} km` : "—";
  const routeEta = routeMetrics ? `${Math.max(1, Math.ceil(routeMetrics.durationSeconds / 60))} min` : incident.responderEtaMinutes ? `${incident.responderEtaMinutes} min` : "—";
  return <><PageHeading eyebrow="Active emergency" title={status === "searching" ? "Searching for verified responders." : arrived ? "Help has arrived." : "A responder is on the way."} description={status === "searching" ? "Your request is confirmed and visible only to eligible verified responders." : arrived ? "Confirm resolution when the immediate need for help has ended." : "This protected view updates as the assigned responder progresses through the request."} action={<StatusBadge tone={incidentTone(status)} label={incidentStatusLabel(status)} />} /><div className="grid gap-6 2xl:grid-cols-[1.2fr_0.8fr]"><EmergencyMap data={mapData} onRouteMetrics={onRouteMetrics} label={status === "searching" ? "Responder search area" : "Authorized live route"} /><div className="space-y-4"><SurfaceCard tone={incidentTone(status)} className="p-6"><div className="flex items-center justify-between"><StatusBadge tone={incidentTone(status)} label={incident.publicId} /><span className="rn-mono text-xs font-semibold text-[#60707c]">{new Date(incident.updatedAt).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}</span></div><h2 className="mt-4 text-2xl font-extrabold tracking-[-0.05em]">{emergencyLabel[incident.emergencyType]}</h2><p className="mt-2 flex items-center gap-2 text-sm font-semibold text-[#52626c]"><MapPin className="h-4 w-4 text-[#d83232]" />{incident.locationLabel}</p>{incident.description && <p className="mt-3 border-t border-[#edf0ee] pt-3 text-sm font-medium leading-6 text-[#52626c]">{incident.description}</p>}<div className="mt-5 grid grid-cols-3 gap-3 border-t border-[#edf0ee] pt-5"><div><p className="text-[0.65rem] font-extrabold uppercase tracking-[0.1em] text-[#60707c]">Responder</p><p className="mt-1 font-extrabold">{incident.responderName ?? "Matching in progress"}</p></div><div><p className="text-[0.65rem] font-extrabold uppercase tracking-[0.1em] text-[#60707c]">Route</p><p className="mt-1 font-extrabold text-[#0e4e78]">{routeDistance}</p></div><div><p className="text-[0.65rem] font-extrabold uppercase tracking-[0.1em] text-[#60707c]">ETA</p><p className="mt-1 font-extrabold text-[#d83232]">{routeEta}</p></div></div><Button disabled={simulate.isPending || resolve.isPending} onClick={advance} className={`rn-touch mt-6 w-full text-sm font-extrabold text-white ${arrived ? "bg-[#247352] hover:bg-[#1b5239]" : "bg-[#0e4e78] hover:bg-[#0b3e61]"}`}>{simulate.isPending || resolve.isPending ? "Confirming update…" : actionLabel}</Button>{["accepted", "en_route"].includes(status) && <Button disabled={simulateMovement.isPending} onClick={moveResponder} variant="outline" className="rn-touch mt-3 w-full border-[#0e4e78] text-sm font-extrabold text-[#0e4e78]">{simulateMovement.isPending ? "Updating responder position…" : "Refresh responder position"}</Button>}</SurfaceCard><OperationalAlert tone="info" title="Live emergency map">The route, distance, ETA, hospital markers, and responder position are derived from the authorized incident map. Current location remains local unless you confirm an emergency request.</OperationalAlert><SurfaceCard tone="neutral" className="p-5"><p className="rn-eyebrow">Response timeline</p><div className="mt-3 space-y-3">{timeline.data?.map(event => <div key={event.id} className="border-l-2 border-[#0e4e78] pl-3"><p className="text-xs font-extrabold text-[#17212b]">{event.note}</p><p className="mt-1 rn-mono text-[0.62rem] text-[#60707c]">{new Date(event.createdAt).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}</p></div>) ?? <p className="text-xs font-semibold text-[#60707c]">Loading verified timeline…</p>}</div></SurfaceCard><StatePreview compact /></div></div></>;
}

function CitizenRequestResolved({ incident }: { incident: { publicId: string; emergencyType: CitizenEmergencyType; locationLabel: string } }) { const { resetDraft } = useEmergencyDraft(); return <><PageHeading eyebrow="Incident resolved" title="Emergency request completed." description="The incident is retained as a protected response record. Thank you for confirming that the immediate need has ended." action={<StatusBadge tone="safe" label="Resolved" />} /><div className="grid gap-6 xl:grid-cols-[1fr_0.55fr]"><SurfaceCard tone="safe" className="p-6"><CheckCircle2 className="h-9 w-9 text-[#247352]" /><h2 className="mt-4 text-2xl font-extrabold tracking-[-0.05em]">Help arrived and this request is resolved.</h2><p className="mt-2 text-sm font-medium leading-6 text-[#52626c]">{incident.publicId} · {emergencyLabel[incident.emergencyType]} · {incident.locationLabel}</p><div className="mt-6 flex flex-wrap gap-3"><Link onClick={resetDraft} href="/citizen" className="rn-focus flex min-h-11 items-center rounded-lg bg-[#0e4e78] px-4 text-sm font-extrabold text-white">Return home</Link><Link href="/citizen/history" className="rn-focus flex min-h-11 items-center rounded-lg border border-[#cbd5d6] bg-white px-4 text-sm font-extrabold text-[#0e4e78]">View incident history</Link></div></SurfaceCard><OperationalAlert tone="info" title="Response record">Only authorized information remains available in your incident history.</OperationalAlert></div></>;
}

function CitizenRequestHistory() { const history = trpc.incidents.mine.useQuery(); return <><PageHeading eyebrow="Incident history" title="Your verified response records." description="Only incidents created by this citizen account are shown here." /><div className="grid gap-6 xl:grid-cols-[1fr_0.48fr]"><SurfaceCard tone="neutral" className="p-6"><div className="mb-3 flex items-center justify-between"><p className="text-sm font-extrabold">Response records</p><StatusBadge tone="safe" label={`${history.data?.filter(item => item.status === "resolved").length ?? 0} resolved`} /></div>{history.isLoading ? <p className="py-6 text-sm font-semibold text-[#60707c]">Loading protected records…</p> : history.data?.length ? history.data.map(item => <Link key={item.id} href={`/citizen/live/${item.publicId}`} className="block border-b border-[#edf0ee] py-4 last:border-b-0"><div className="flex items-center justify-between gap-3"><div><p className="text-sm font-extrabold text-[#17212b]">{emergencyLabel[item.emergencyType]}</p><p className="mt-1 text-xs font-semibold text-[#60707c]">{item.publicId} · {item.locationLabel}</p></div><StatusBadge tone={incidentTone(item.status)} label={incidentStatusLabel(item.status)} /></div></Link>) : <div className="rounded-lg border border-dashed border-[#cad4d5] p-4"><p className="text-sm font-extrabold text-[#43535e]">No incident records yet.</p><p className="mt-1 text-xs font-medium text-[#60707c]">Your confirmed emergency requests will appear here.</p></div>}</SurfaceCard><div className="space-y-4"><OperationalAlert tone="info" title="Privacy and retention">Location history is available only for active coordination and approved incident records.</OperationalAlert><StatePreview compact /></div></div></>;
}

function CitizenHome() { return <><PageHeading eyebrow="Citizen home" title="Emergency status: no active request." description="If someone needs immediate help, begin with a clear category and confirmed location. RANEEV will show the verified next action at each step." action={<Link href="/citizen/report" className="rn-focus flex min-h-12 items-center justify-center gap-2 rounded-md bg-[#d83232] px-5 text-sm font-extrabold text-white hover:bg-[#b82727]"><AlertTriangle className="h-4 w-4" />Report emergency</Link>} /><div className="grid gap-5 xl:grid-cols-[1.15fr_0.85fr]"><SurfaceCard tone="info" className="p-6"><div className="flex items-start justify-between gap-4"><div><StatusBadge tone="safe" label="No active incident" /><h2 className="mt-5 text-2xl font-extrabold tracking-[-0.05em]">Start with the facts you know.</h2><p className="mt-2 max-w-lg text-sm font-medium leading-6 text-[#52626c]">Choose an emergency category, confirm the location, and review the request before RANEEV begins a responder search.</p></div><HeartPulse className="h-10 w-10 shrink-0 text-[#0e4e78]" /></div><div className="mt-7 grid gap-0 border-y border-[#d7dddc] sm:grid-cols-3">{[["01", "Choose", "Category"], ["02", "Confirm", "Location"], ["03", "Request", "Help"]].map(([n, a, b], index) => <div key={n} className={`bg-[#f4f7f7] p-3 ${index > 0 ? "border-t border-[#d7dddc] sm:border-l sm:border-t-0" : ""}`}><span className="rn-mono text-xs font-bold text-[#0e4e78]">{n}</span><p className="mt-2 text-sm font-extrabold">{a}</p><p className="text-xs font-semibold text-[#60707c]">{b}</p></div>)}</div></SurfaceCard><div className="space-y-4"><OperationalAlert tone="warning" title="Location accuracy matters">Move to an open area or adjust the pin manually if your location appears inaccurate.</OperationalAlert><SurfaceCard tone="neutral" className="p-5"><div className="flex items-center justify-between"><div><p className="rn-eyebrow">Emergency history</p><p className="mt-2 text-sm font-extrabold">2 resolved incidents</p></div><Link href="/citizen/history" className="rn-focus text-xs font-extrabold text-[#0e4e78]">View history</Link></div></SurfaceCard></div></div><div className="mt-6"><StatePreview /></div></>; }

function CitizenReport() { return <><BackLink href="/citizen" label="Citizen home" /><PageHeading eyebrow="Emergency reporting · step 1 of 3" title="What kind of help is needed?" description="Choose the closest operational category. This is not a medical diagnosis. You can add a short note on the next screen." /><div className="grid gap-6 xl:grid-cols-[1fr_0.62fr]"><SurfaceCard tone="critical" className="p-6"><div className="grid gap-3 sm:grid-cols-2">{[["Medical emergency", "Collapse, breathing concern, severe pain"], ["Road accident", "Vehicle incident or roadside injury"], ["Injury", "Fall, wound, or assistance needed"], ["Fire concern", "Small fire or immediate safety support"], ["Unconscious person", "Person not responding"], ["Other", "Describe the immediate situation"]].map(([title, text], index) => <button key={title} onClick={() => toast(`Selected ${title} for UI preview. The backend will record this safely.`)} className={`rn-focus min-h-28 rounded-xl border p-4 text-left ${index === 1 ? "border-[#0e4e78] bg-[#e2eff6]" : "border-[#d7dddc] bg-white hover:border-[#0e4e78]"}`}><p className="text-sm font-extrabold text-[#17212b]">{title}</p><p className="mt-2 text-xs font-medium leading-5 text-[#60707c]">{text}</p></button>)}</div><div className="mt-6 flex justify-end"><Link href="/citizen/confirm" className="rn-focus flex min-h-12 items-center gap-2 rounded-xl bg-[#0e4e78] px-5 text-sm font-extrabold text-white hover:bg-[#0b3e61]">Continue to confirmation <ArrowRight className="h-4 w-4" /></Link></div></SurfaceCard><div className="space-y-4"><OperationalAlert tone="critical" title="If there is immediate danger">Contact local professional emergency services first whenever available. RANEEV is designed to coordinate nearby community help.</OperationalAlert><SurfaceCard tone="info" className="p-5"><p className="rn-eyebrow">Location check</p><p className="mt-3 text-sm font-extrabold">Current location will be requested next.</p><p className="mt-2 text-xs font-medium leading-5 text-[#60707c]">The backend will validate coordinates, accuracy, and your permission to create an incident.</p></SurfaceCard><StatePreview compact /></div></div></>; }

function CitizenConfirm() { return <><BackLink href="/citizen/report" label="Edit emergency details" /><PageHeading eyebrow="Emergency reporting · step 2 of 3" title="Confirm the incident location." description="Review the category and location before a responder search begins. No request is sent in this frontend-only prototype." /><div className="grid gap-6 xl:grid-cols-[1fr_0.65fr]"><MapSurface label="Location confirmation preview" tall /><div className="space-y-4"><SurfaceCard tone="critical" className="p-6"><StatusBadge tone="critical" label="Road accident" /><h2 className="mt-4 text-xl font-extrabold tracking-[-0.04em]">NH 44 service road, Devanahalli</h2><p className="mt-2 text-sm font-medium leading-6 text-[#60707c]">Location precision: 18 m · Last checked at 11:42</p><div className="mt-5 border-y border-[#edf0ee] py-4"><p className="rn-eyebrow">Short description</p><p className="mt-2 text-sm font-semibold text-[#43535e]">“Two-wheeler incident near the service lane. Person is conscious.”</p></div><DemoAction emergency className="mt-5 w-full">Confirm emergency request</DemoAction><p className="mt-3 text-center text-xs font-semibold text-[#60707c]">You will see responder search status after the server confirms the request.</p></SurfaceCard><DetailDialog /><StatePreview compact /></div></div></>; }

function CitizenLive() { return <><PageHeading eyebrow="Active emergency" title="A responder is on the way." description="This screen presents the authorized incident view. Coordinates, responder details, and event updates will be confirmed by the backend." action={<StatusBadge tone="critical" label="Responder en route" />} /><div className="grid gap-6 2xl:grid-cols-[1.2fr_0.8fr]"><MapSurface label="Authorized live route" tall /><div className="space-y-4"><SurfaceCard tone="critical" className="p-6"><div className="flex items-center justify-between"><StatusBadge tone="critical" label="ERN-2408-184" /><span className="rn-mono text-xs font-semibold text-[#60707c]">11:42</span></div><h2 className="mt-4 text-2xl font-extrabold tracking-[-0.05em]">{demoIncident.category}</h2><p className="mt-2 flex items-center gap-2 text-sm font-semibold text-[#52626c]"><MapPin className="h-4 w-4 text-[#d83232]" />{demoIncident.location}</p><div className="mt-5 grid grid-cols-2 gap-3 border-t border-[#edf0ee] pt-5"><div><p className="text-[0.65rem] font-extrabold uppercase tracking-[0.1em] text-[#60707c]">Responder</p><p className="mt-1 font-extrabold">{demoIncident.responder}</p></div><div><p className="text-[0.65rem] font-extrabold uppercase tracking-[0.1em] text-[#60707c]">ETA</p><p className="mt-1 font-extrabold text-[#d83232]">{demoIncident.eta}</p></div></div></SurfaceCard><OperationalAlert tone="info" title="Share only relevant details">The assigned responder can see the active incident location. Personal information remains restricted.</OperationalAlert><DemoAction className="w-full">Contact support channel</DemoAction><StatePreview compact /></div></div></>; }

function CitizenHistory() { return <><PageHeading eyebrow="Incident history" title="Your past response records." description="Only authorized details will be retained and displayed when the backend and retention controls are connected." /><div className="grid gap-6 xl:grid-cols-[1fr_0.48fr]"><SurfaceCard tone="neutral" className="p-6"><div className="mb-3 flex items-center justify-between"><p className="text-sm font-extrabold">Resolved incidents</p><StatusBadge tone="safe" label="2 records" /></div>{incidents.filter((item) => item.tone === "safe").map((incident) => <IncidentRow key={incident.id} incident={incident} detailed />)}<div className="mt-5 rounded-lg border border-dashed border-[#cad4d5] p-4"><p className="text-sm font-extrabold text-[#43535e]">No other records in this demo account.</p><p className="mt-1 text-xs font-medium text-[#60707c]">The empty-state treatment is ready for accounts without incident history.</p></div></SurfaceCard><div className="space-y-4"><OperationalAlert tone="info" title="Privacy and retention">Location history should be retained only for active coordination and approved audit purposes.</OperationalAlert><StatePreview compact /></div></div></>; }

function CitizenProfile() { return <><PageHeading eyebrow="Citizen profile" title="Your information and preferences." description="This form demonstrates validated fields and safe status messaging. Saving will connect to the protected profile API in a later phase." /><div className="grid gap-6 xl:grid-cols-[1fr_0.52fr]"><SurfaceCard tone="neutral" className="p-6"><div className="grid gap-4 sm:grid-cols-2">{[["Full name", "Saanvi Kulkarni"], ["Phone", "+91 98••• 4321"], ["Email", "saanvi@example.com"], ["Emergency language", "English"]].map(([label, value]) => <label key={label} className="block"><span className="text-xs font-extrabold text-[#43535e]">{label}</span><input className="rn-focus mt-2 min-h-12 w-full rounded-lg border border-[#cbd5d6] bg-white px-3 text-sm font-semibold" defaultValue={value} /></label>)}</div><DemoAction className="mt-6">Save profile changes</DemoAction></SurfaceCard><div className="space-y-4"><SurfaceCard tone="info" className="p-5"><p className="rn-eyebrow">Emergency contacts</p><p className="mt-2 text-sm font-extrabold">Not configured</p><p className="mt-1 text-xs font-medium leading-5 text-[#60707c]">The empty state will guide a user through adding optional contacts after backend policy is confirmed.</p></SurfaceCard><StatePreview compact /></div></div></>; }

export function VolunteerPortal({ page }: { page?: string }) { return <VolunteerMode page={page} />; }

function VolunteerHome() { return <><PageHeading eyebrow="Volunteer dashboard" title="Your response readiness." description="Keep availability, location permission, and skill verification current before accepting emergency assignments." action={<StatusBadge tone="safe" label="Available" />} /><div className="grid gap-5 md:grid-cols-3"><Metric label="Response radius" value="5 km" sub="Configured range" tone="info" /><Metric label="Verified skills" value="03" sub="First aid · CPR · rescue" tone="safe" /><Metric label="Response record" value="12" sub="Completed incidents" tone="info" /></div><div className="mt-6 grid gap-6 xl:grid-cols-[1.1fr_0.9fr]"><SurfaceCard tone="safe" className="p-6"><div className="flex items-start justify-between"><div><StatusBadge tone="safe" label="Ready to receive alerts" /><h2 className="mt-4 text-2xl font-extrabold tracking-[-0.05em]">You are visible to nearby incident matching.</h2><p className="mt-2 text-sm font-medium leading-6 text-[#52626c]">Availability will be confirmed by the backend alongside your verification state and last known permitted location.</p></div><Radio className="h-8 w-8 text-[#247352]" /></div><div className="mt-6 flex flex-wrap gap-3"><Link href="/volunteer/availability" className="rn-focus flex min-h-11 items-center rounded-lg bg-[#0e4e78] px-4 text-sm font-extrabold text-white">Review availability</Link><Link href="/volunteer/nearby" className="rn-focus flex min-h-11 items-center rounded-lg border border-[#cbd5d6] bg-white px-4 text-sm font-extrabold text-[#0e4e78]">Preview nearby alert</Link></div></SurfaceCard><div className="space-y-4"><OperationalAlert tone="warning" title="Never travel beyond your training">Accept only incidents you can safely support. Professional emergency services remain the priority.</OperationalAlert><StatePreview compact /></div></div></>; }

function VolunteerAvailability() { return <><PageHeading eyebrow="Availability" title="Control when you can respond." description="Availability is a protected operational state. The frontend preview does not alter responder eligibility or broadcast location." /><div className="grid gap-6 xl:grid-cols-[0.8fr_1.2fr]"><SurfaceCard tone="safe" className="p-6"><StatusBadge tone="safe" label="Currently available" /><h2 className="mt-4 text-2xl font-extrabold tracking-[-0.05em]">Available within 5 km</h2><p className="mt-2 text-sm font-medium leading-6 text-[#60707c]">Last location permission check: 11:36 · Accuracy: 24 m</p><DemoAction className="mt-6 w-full">Update availability</DemoAction></SurfaceCard><SurfaceCard tone="info" className="p-6"><p className="rn-eyebrow">Readiness checklist</p><div className="mt-4 space-y-3">{[["Identity verification", "Approved", "safe"], ["First-aid skill evidence", "Approved", "safe"], ["Location permission", "Needs refresh", "warning"], ["Active assignment", "None", "neutral"]].map(([label, status, tone]) => <div key={label} className="flex items-center justify-between border-b border-[#edf0ee] py-3"><p className="text-sm font-extrabold">{label}</p><StatusBadge tone={tone as never} label={status} /></div>)}</div></SurfaceCard></div><div className="mt-6"><StatePreview /></div></>; }

function VolunteerNearby() { return <><PageHeading eyebrow="Nearby emergency alert" title="A request is available to review." description="Before acceptance, show only the information required to assess safety, distance, and appropriate skill fit." action={<StatusBadge tone="critical" label="Needs response" />} /><div className="grid gap-6 xl:grid-cols-[1.1fr_0.9fr]"><MapSurface label="Approximate incident area" /><SurfaceCard tone="critical" className="p-6"><div className="flex items-center justify-between"><StatusBadge tone="critical" label="Road accident" /><span className="rn-mono text-xs font-semibold text-[#60707c]">ERN-2408-184</span></div><h2 className="mt-4 text-2xl font-extrabold tracking-[-0.05em]">2.4 km away</h2><p className="mt-2 text-sm font-medium leading-6 text-[#52626c]">Possible roadside injury near NH 44 service road. Full location is available after a valid assignment.</p><div className="mt-5 grid grid-cols-2 gap-3 border-y border-[#edf0ee] py-4"><div><p className="rn-eyebrow">Skill fit</p><p className="mt-1 text-sm font-extrabold text-[#247352]">First aid matched</p></div><div><p className="rn-eyebrow">Alert age</p><p className="mt-1 text-sm font-extrabold">02 min</p></div></div><Link href="/volunteer/accept" className="rn-focus mt-5 flex min-h-12 items-center justify-center gap-2 rounded-xl bg-[#0e4e78] text-sm font-extrabold text-white hover:bg-[#0b3e61]">Review acceptance <ArrowRight className="h-4 w-4" /></Link></SurfaceCard></div><div className="mt-6"><StatePreview /></div></>; }

function VolunteerAccept() { return <><BackLink href="/volunteer/nearby" label="Back to alert" /><PageHeading eyebrow="Assignment decision" title="Can you safely respond?" description="Review the incident summary and confirm only if you are available, appropriately trained, and able to travel safely." /><div className="grid gap-6 xl:grid-cols-[1fr_0.58fr]"><SurfaceCard tone="critical" className="p-6"><div className="grid gap-5 sm:grid-cols-2"><div><p className="rn-eyebrow">Incident</p><p className="mt-2 text-xl font-extrabold">Road accident</p><p className="mt-1 text-sm font-semibold text-[#60707c]">2.4 km · Request age 02 min</p></div><div><p className="rn-eyebrow">Your profile</p><p className="mt-2 text-xl font-extrabold">First aid · CPR</p><p className="mt-1 text-sm font-semibold text-[#60707c]">Available · 5 km radius</p></div></div><OperationalAlert tone="warning" title="Safety confirmation"><span>Do not accept if you cannot respond safely. The backend will lock a valid acceptance to prevent duplicate primary assignments.</span></OperationalAlert><div className="mt-5 flex flex-col gap-3 sm:flex-row"><DemoAction className="flex-1">Accept response request</DemoAction><Button onClick={() => toast("Rejection will be recorded with an optional reason when the backend is connected.")} variant="outline" className="rn-touch flex-1 border-[#cbd5d6] font-extrabold text-[#43535e]">Decline safely</Button></div></SurfaceCard><div className="space-y-4"><DetailDialog /><StatePreview compact /></div></div></>; }

function VolunteerActive() { return <><PageHeading eyebrow="Active response" title="Navigate with care." description="Your location sharing and incident state are limited to the active, authorized assignment." action={<StatusBadge tone="critical" label="En route" />} /><div className="grid gap-6 2xl:grid-cols-[1.2fr_0.8fr]"><MapSurface label="Active route preview" tall /><div className="space-y-4"><SurfaceCard tone="critical" className="p-6"><p className="rn-eyebrow">ERN-2408-184</p><h2 className="mt-2 text-2xl font-extrabold tracking-[-0.05em]">2.4 km · 06 min ETA</h2><p className="mt-2 text-sm font-medium leading-6 text-[#52626c]">Road accident · NH 44 service road</p><div className="mt-5 grid gap-2"><DemoAction>Mark as arrived</DemoAction><Button onClick={() => toast("Navigation handoff is a UI preview only.")} variant="outline" className="rn-touch border-[#cbd5d6] font-extrabold text-[#0e4e78]"><Navigation className="mr-2 h-4 w-4" />Open navigation</Button></div></SurfaceCard><OperationalAlert tone="info" title="Location sharing is active for this response">Sharing should end automatically when the incident closes or assignment is revoked.</OperationalAlert><StatePreview compact /></div></div></>; }

function VolunteerHistory() { return <><PageHeading eyebrow="Response history" title="Your completed responses." description="History records will be generated from audited incident events after backend integration." /><div className="grid gap-6 xl:grid-cols-[1fr_0.45fr]"><SurfaceCard tone="safe" className="p-6"><div className="mb-3 flex items-center justify-between"><p className="text-sm font-extrabold">Completed responses</p><StatusBadge tone="safe" label="12 total" /></div>{incidents.map((incident) => <IncidentRow key={incident.id} incident={{ ...incident, tone: "safe", status: "Completed" }} detailed />)}</SurfaceCard><div className="space-y-4"><Metric label="Median arrival" value="11 min" sub="Demo-period metric" tone="info" /><StatePreview compact /></div></div></>; }

function VolunteerProfile() { return <><PageHeading eyebrow="Verification and profile" title="Your responder credentials." description="Identity and skill evidence are protected records. This UI uses mock data only until secure storage and review workflows are implemented." /><div className="grid gap-6 xl:grid-cols-[1fr_0.55fr]"><SurfaceCard tone="safe" className="p-6"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-xl font-extrabold">Ananya Rao</p><p className="mt-1 text-sm font-semibold text-[#60707c]">Volunteer responder · Bengaluru Rural</p></div><StatusBadge tone="safe" label="Verified" /></div><div className="mt-6 grid gap-3 sm:grid-cols-3">{[["Identity", "Approved"], ["First aid", "Verified"], ["CPR", "Verified"]].map(([label, status]) => <div key={label} className="rounded-lg bg-[#f2faf5] p-4"><p className="text-xs font-extrabold text-[#43535e]">{label}</p><p className="mt-2 text-sm font-extrabold text-[#247352]">{status}</p></div>)}</div><DemoAction className="mt-6">Update responder profile</DemoAction></SurfaceCard><div className="space-y-4"><OperationalAlert tone="info" title="Document privacy">Verification documents should use private storage and short-lived authorized access links.</OperationalAlert><StatePreview compact /></div></div></>; }

export function CoordinatorPortal({ page }: { page?: string }) { const view = page ?? "home"; const content = view === "ghr" ? <GoldenHourResponse /> : view === "incidents" ? <CoordinatorIncidents /> : view === "details" ? <CoordinatorDetails /> : view === "map" ? <CoordinatorMap /> : view === "responders" ? <CoordinatorResponders /> : view === "analytics" ? <CoordinatorAnalytics /> : <CoordinatorHome />; return <ConsoleShell role="coordinator">{content}</ConsoleShell>; }

function CoordinatorHome() { return <CoordinatorCommandCenter />; }

function CoordinatorIncidents() { return <><PageHeading eyebrow="Incident list" title="All monitored incidents." description="Filters and live data will be supplied by the protected incident API. This screen demonstrates prioritization and state design." /><SurfaceCard tone="neutral" className="p-6"><div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div className="flex flex-wrap gap-2"><StatusBadge tone="critical" label="Active" /><StatusBadge tone="warning" label="Matching" /><StatusBadge tone="safe" label="Resolved" /></div><button onClick={() => toast("Search will be implemented against the incident API.")} className="rn-focus flex min-h-10 items-center gap-2 rounded-lg border border-[#cbd5d6] bg-white px-3 text-xs font-extrabold text-[#43535e]"><Search className="h-4 w-4" />Search incident ID</button></div><div className="mt-4">{incidents.map((incident) => <IncidentRow key={incident.id} incident={incident} detailed />)}</div><div className="mt-5"><StatePreview compact /></div></SurfaceCard></>; }

function CoordinatorDetails() { return <><PageHeading eyebrow="Incident detail" title="ERN-2408-184" description="A controlled, auditable view of the current incident state and authorized participants." action={<StatusBadge tone="critical" label="Responder en route" />} /><div className="grid gap-6 2xl:grid-cols-[1.1fr_0.9fr]"><div className="space-y-6"><MapSurface label="Live incident context" /><SurfaceCard tone="critical" className="p-6"><p className="rn-eyebrow">Timeline</p><div className="mt-5 space-y-0">{auditEvents.map((event, index) => <div key={event.time} className="relative flex gap-4 pb-5 last:pb-0"><span className={`mt-1 h-3 w-3 rounded-full border-2 border-white ${index === auditEvents.length - 1 ? "bg-[#d83232]" : "bg-[#0e4e78]"} shadow-[0_0_0_1px_#cbd5d6]`} /><div><p className="text-sm font-extrabold">{event.action}</p><p className="mt-1 text-xs font-semibold text-[#60707c]">{event.time} · {event.actor} · {event.detail}</p></div></div>)}</div></SurfaceCard></div><div className="space-y-4"><SurfaceCard tone="info" className="p-6"><p className="rn-eyebrow">Primary responder</p><p className="mt-2 text-xl font-extrabold">Ananya Rao</p><p className="mt-1 text-sm font-semibold text-[#60707c]">First aid · CPR · 2.4 km · Last update 11:47</p><DemoAction className="mt-5 w-full">Open coordinator intervention</DemoAction></SurfaceCard><OperationalAlert tone="info" title="Access is role-scoped">Every coordinator review, access, and state intervention should create an audit event.</OperationalAlert><StatePreview compact /></div></div></>; }

function CoordinatorMap() { return <><PageHeading eyebrow="Live map" title="Operational field view." description="Use map overlays for incidents, responder locations, response status, and safe geographic context." /><div className="grid gap-6 xl:grid-cols-[1.25fr_0.75fr]"><MapSurface label="Pilot-area situation map" tall /><SurfaceCard tone="info" className="p-6"><p className="rn-eyebrow">Map overlays</p><div className="mt-4 space-y-3">{[["Signal Red", "Active emergency", "critical"], ["Maritime Blue", "Responder route", "info"], ["Response Green", "Resolved / available", "safe"], ["Amber", "Attention or degraded state", "warning"]].map(([label, text, tone]) => <div key={label} className="flex items-center justify-between border-b border-[#edf0ee] py-3"><div><p className="text-sm font-extrabold">{label}</p><p className="mt-1 text-xs font-semibold text-[#60707c]">{text}</p></div><StatusBadge tone={tone as never} /></div>)}</div><div className="mt-5"><StatePreview compact /></div></SurfaceCard></div></>; }

function CoordinatorResponders() { return <><PageHeading eyebrow="Responder management" title="Nearby verified responders." description="View availability, training, current assignment state, and response range without exposing unnecessary personal data." /><div className="grid gap-5 xl:grid-cols-[1fr_0.42fr]"><SurfaceCard tone="neutral" className="p-6"><div className="mb-3 flex items-center justify-between"><p className="text-sm font-extrabold">Responder network</p><span className="rn-mono text-xs font-semibold text-[#60707c]">48 active</span></div>{responders.map((responder) => <div key={responder.name} className="flex flex-col gap-3 border-b border-[#edf0ee] py-4 last:border-b-0 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-center gap-3"><span className="flex h-10 w-10 items-center justify-center rounded-full bg-[#e2eff6] text-xs font-extrabold text-[#0e4e78]">{responder.initials}</span><div><p className="text-sm font-extrabold">{responder.name}</p><p className="mt-1 text-xs font-semibold text-[#60707c]">{responder.skill} · {responder.range}</p></div></div><StatusBadge tone={responder.tone} label={responder.status} /></div>)}</SurfaceCard><div className="space-y-4"><OperationalAlert tone="warning" title="Stale location policy">Responders with stale or inaccurate permitted locations should be excluded from matching until updated.</OperationalAlert><StatePreview compact /></div></div></>; }

function CoordinatorAnalytics() { return <><PageHeading eyebrow="Response analytics" title="Measure the time that matters." description="The MVP should track emergency activation to responder acceptance before optimizing secondary metrics." /><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4"><Metric label="Activation → accepted" value="03:12" sub="Median · today" tone="critical" /><Metric label="Match success" value="82%" sub="Pilot-area requests" tone="safe" /><Metric label="Responder arrival" value="13m" sub="Median · today" tone="info" /><Metric label="Location reliability" value="96%" sub="Active sessions" tone="warning" /></div><div className="mt-6 grid gap-6 xl:grid-cols-[1.1fr_0.9fr]"><SurfaceCard tone="info" className="p-6"><p className="rn-eyebrow">Acceptance time trend</p><div className="mt-6 flex h-48 items-end gap-3 border-b border-l border-[#d7dddc] px-5 pb-5">{[42, 58, 45, 69, 56, 78, 63, 88, 72].map((height, index) => <div key={index} className="flex flex-1 flex-col items-center justify-end gap-2"><span className="w-full rounded-t-sm bg-[#0e4e78]" style={{ height: `${height}%` }} /><span className="rn-mono text-[0.58rem] text-[#60707c]">{index + 1}</span></div>)}</div><p className="mt-4 text-xs font-semibold text-[#60707c]">Illustrative UI data only. Production metrics will derive from audited incident events.</p></SurfaceCard><StatePreview /></div></>; }

export function AdminPortal({ page }: { page?: string }) { const view = page ?? "home"; const content = view === "users" ? <AdminUsers /> : view === "verification" ? <AdminVerification /> : view === "incidents" ? <AdminIncidents /> : view === "audit" ? <AdminAudit /> : view === "ai" ? <AdminAiActivity /> : <AdminHome />; return <ConsoleShell role="admin">{content}</ConsoleShell>; }

function AdminHome() { return <><PageHeading eyebrow="Administration" title="Govern the responder network." description="Administrative tools are designed for review, accountability, and controlled intervention—not routine incident dispatch." /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Pending verification" value="04" sub="Requires reviewer action" tone="warning" /><Metric label="Active users" value="1,284" sub="Pilot tenant" tone="info" /><Metric label="Suspended profiles" value="02" sub="Review required" tone="critical" /><Metric label="Audit events" value="164" sub="Today" tone="safe" /></div><div className="mt-6 grid gap-6 xl:grid-cols-[1.1fr_0.9fr]"><SurfaceCard tone="warning" className="p-6"><p className="text-lg font-extrabold">Verification queue</p><div className="mt-4 space-y-3">{[["Rohan Iyer", "Identity + first aid certificate", "18 min ago"], ["Fatima Khan", "Nursing credential", "42 min ago"], ["Vikram Patel", "Basic rescue evidence", "1 h ago"]].map(([name, item, time]) => <div key={name} className="flex items-center justify-between gap-4 border-b border-[#edf0ee] pb-3 last:border-b-0"><div><p className="text-sm font-extrabold">{name}</p><p className="mt-1 text-xs font-semibold text-[#60707c]">{item}</p></div><span className="rn-mono text-[0.62rem] font-semibold text-[#60707c]">{time}</span></div>)}</div><Link href="/admin/verification" className="rn-focus mt-5 inline-flex min-h-10 items-center gap-2 text-xs font-extrabold text-[#0e4e78]">Open review queue <ChevronRight className="h-4 w-4" /></Link></SurfaceCard><div className="space-y-4"><OperationalAlert tone="critical" title="Admin actions are auditable">Approval, suspension, access review, and incident interventions should all create immutable security audit records.</OperationalAlert><StatePreview compact /></div></div></>; }

function AdminUsers() { return <><PageHeading eyebrow="User management" title="Accounts and access state." description="This UI demonstrates a protected list with clear status language. User records will be provided by the backend and authorization layer." /><SurfaceCard tone="neutral" className="p-6">{[["Saanvi Kulkarni", "Citizen", "Active", "safe"], ["Ananya Rao", "Volunteer", "Verified", "safe"], ["Kiran Shah", "Volunteer", "Pending review", "warning"], ["User 4821", "Citizen", "Suspended", "critical"]].map(([name, role, state, tone]) => <div key={name} className="flex flex-col gap-3 border-b border-[#edf0ee] py-4 last:border-b-0 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-sm font-extrabold">{name}</p><p className="mt-1 text-xs font-semibold text-[#60707c]">{role} · ID masked until authorized lookup</p></div><div className="flex items-center gap-3"><StatusBadge tone={tone as never} label={state} /><Button onClick={() => toast("User actions require secure backend authorization.")} variant="outline" className="min-h-10 border-[#cbd5d6] text-xs font-extrabold">Review</Button></div></div>)}<div className="mt-5"><StatePreview compact /></div></SurfaceCard></>; }

function AdminVerification() { return <><PageHeading eyebrow="Volunteer verification" title="Review evidence with care." description="Identity and skill documentation must remain private. This mock queue shows the review shell, not real submitted records." /><div className="grid gap-6 xl:grid-cols-[1fr_0.58fr]"><SurfaceCard tone="warning" className="p-6"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-xl font-extrabold">Rohan Iyer</p><p className="mt-1 text-sm font-semibold text-[#60707c]">Volunteer application · Submitted 18 min ago</p></div><StatusBadge tone="warning" label="Pending review" /></div><div className="mt-6 grid gap-3 sm:grid-cols-2">{[["Identity evidence", "Private document preview"], ["Skill evidence", "First aid certificate"], ["Response radius", "5 km requested"], ["Categories", "Medical · injury"]].map(([label, value]) => <div key={label} className="rounded-lg bg-[#fffaf0] p-4"><p className="text-xs font-extrabold text-[#43535e]">{label}</p><p className="mt-2 text-sm font-extrabold text-[#17212b]">{value}</p></div>)}</div><div className="mt-6 flex flex-col gap-3 sm:flex-row"><DemoAction className="flex-1">Approve verification</DemoAction><Button onClick={() => toast("Rejection workflow will require a reason and audit entry.")} variant="outline" className="rn-touch flex-1 border-[#cbd5d6] font-extrabold">Request clarification</Button></div></SurfaceCard><div className="space-y-4"><OperationalAlert tone="info" title="Sensitive-document policy">Private file storage, reviewer permissions, signed URLs, and retention rules will be implemented with the backend.</OperationalAlert><StatePreview compact /></div></div></>; }

function AdminIncidents() { return <><PageHeading eyebrow="Incident management" title="Review high-impact incident records." description="Administrative intervention should be exceptional, documented, and constrained by role policy." /><div className="grid gap-6 xl:grid-cols-[1fr_0.45fr]"><SurfaceCard tone="critical" className="p-6">{incidents.map((incident) => <IncidentRow key={incident.id} incident={incident} detailed />)}<div className="mt-5"><StatePreview compact /></div></SurfaceCard><div className="space-y-4"><OperationalAlert tone="warning" title="Intervention guardrail">The backend will verify role, incident state, and reason before allowing forced cancellation or reassignment.</OperationalAlert><DetailDialog /></div></div></>; }

function AdminAudit() { return <><PageHeading eyebrow="Audit logs" title="Protected operational trail." description="Security-sensitive actions need actor, time, target, correlation context, and immutable event history." /><SurfaceCard tone="info" className="p-6"><div className="hidden grid-cols-[0.3fr_1fr_0.8fr_0.7fr] gap-4 border-b border-[#d7dddc] pb-3 text-[0.65rem] font-extrabold uppercase tracking-[0.1em] text-[#60707c] md:grid"><span>Time</span><span>Action</span><span>Actor</span><span>Context</span></div>{auditEvents.map((event) => <div key={event.time} className="grid gap-2 border-b border-[#edf0ee] py-4 text-sm md:grid-cols-[0.3fr_1fr_0.8fr_0.7fr] md:gap-4"><span className="rn-mono text-xs font-semibold text-[#60707c]">{event.time}</span><span className="font-extrabold">{event.action}</span><span className="text-xs font-semibold text-[#52626c]">{event.actor}</span><span className="text-xs font-semibold text-[#52626c]">{event.detail}</span></div>)}<div className="mt-5"><StatePreview compact /></div></SurfaceCard></>; }
